const assert = require('node:assert/strict');
const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const handler = new OrderHandler(new OrderRepository([
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 }
]));
assert.deepEqual(handler.list({ tenant: 'a', limit: 1 }).items.map(x => x.id), ['a']);
assert.equal(handler.list({ tenant: 'a', limit: 1 }).nextCursor, '2026-01-01|a');
assert.deepEqual(handler.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|a' }), {
  items: [{ id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 }], nextCursor: null
});

// Frozen, unsorted input verifies pagination does not mutate the array or its rows.
const rows = Object.freeze([
  { id: 'z', tenant: 'a', createdAt: '2026-01-02', total: 1 },
  { id: 'a', tenant: 'b', createdAt: '2026-01-01', total: 1 },
  { id: 'b', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: '2', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'Z', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: '10', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'zz', tenant: 'b', createdAt: '2026-01-03', total: 1 }
].map(row => Object.freeze(row)));
const repository = new OrderRepository(rows);
const paginated = new OrderHandler(repository);
const expected = ['10', '2', 'Z', 'b', 'z'];
assert.deepEqual(repository.list('a').map(row => row.id), expected);
assert.deepEqual(paginated.list({ tenant: 'a', limit: 100 }).items.map(row => row.id), expected);
assert.equal(paginated.list({ tenant: 'a', limit: 5 }).nextCursor, null);
for (const limit of [1, 2, 3]) {
  let cursor;
  const ids = [];
  do {
    const page = paginated.list({ tenant: 'a', limit, cursor });
    ids.push(...page.items.map(row => row.id));
    assert.ok(ids.length <= expected.length, 'pagination must advance');
    cursor = page.nextCursor;
    if (cursor !== null) {
      const last = page.items.at(-1);
      assert.equal(cursor, last.createdAt + '|' + last.id);
    }
  } while (cursor !== null);
  assert.deepEqual(ids, expected);
}
// Missing/deleted pairs and pairs from another tenant are value boundaries, not row lookups.
for (const cursor of ['2026-01-01|Y', '2026-01-01|a']) {
  assert.deepEqual(paginated.list({ tenant: 'a', limit: 100, cursor }).items.map(row => row.id),
    cursor.endsWith('|Y') ? ['Z', 'b', 'z'] : ['b', 'z']);
}
const mutableRows = rows.slice();
const deleting = new OrderHandler(new OrderRepository(mutableRows));
const first = deleting.list({ tenant: 'a', limit: 2 });
mutableRows.splice(mutableRows.findIndex(row => row.id === '2'), 1);
assert.deepEqual(deleting.list({ tenant: 'a', limit: 100, cursor: first.nextCursor }).items.map(row => row.id),
  ['Z', 'b', 'z']);
for (const request of [
  { tenant: 'missing', limit: 1 },
  { tenant: 'a', limit: 1, cursor: '9999|z' },
  { tenant: 'a', limit: 1, cursor: '2026-01-02|z' }
]) {
  assert.deepEqual(paginated.list(request), { items: [], nextCursor: null });
}
for (const limit of [0, -1, 101, 1.5, NaN, Infinity, '1', null, undefined]) {
  assert.throws(() => paginated.list({ tenant: 'a', limit }), { message: 'invalid request' });
}
assert.throws(() => paginated.list({ tenant: '', limit: 1 }), { message: 'invalid request' });
for (const cursor of ['', '|', '|a', 'date|', 'date|id|extra', 'date||id', null, 42]) {
  assert.throws(() => paginated.list({ tenant: 'a', limit: 1, cursor }), { message: 'invalid request' });
}
